import{_ as l,a as o,b as t}from"./chunks/ruankao_20241024174838.COAcL7iZ.js";import{_ as e,o as i,c as r,at as n}from"./chunks/framework.CY22Hent.js";const p="/assets/ruankao_20241024175904.BzOF6Hxc.png",_="/assets/ruankao_20241024180520.BNZbS2no.png",s="/assets/ruankao_20241024180610.7dvMgKKA.png",f=JSON.parse('{"title":"软件设计师笔记11_标准化和软件知识产权基础知识","description":"","frontmatter":{"title":"软件设计师笔记11_标准化和软件知识产权基础知识","date":"2025-04-05T00:00:00.000Z","lastUpdated":"2025-11-02T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记11_标准化和软件知识产权基础知识.md","filePath":"blogs/软考/软件设计师笔记11_标准化和软件知识产权基础知识.md"}'),c={name:"blogs/软考/软件设计师笔记11_标准化和软件知识产权基础知识.md"};function u(h,a,d,b,k,m){return i(),r("div",null,[...a[0]||(a[0]=[n('<p>[toc]</p><h1 id="软件设计师笔记11-标准化和软件知识产权基础知识" tabindex="-1">软件设计师笔记11_标准化和软件知识产权基础知识 <a class="header-anchor" href="#软件设计师笔记11-标准化和软件知识产权基础知识" aria-label="Permalink to &quot;软件设计师笔记11_标准化和软件知识产权基础知识&quot;">​</a></h1><p>下面的内容参考自《软件设计师教程(第5版)》 这本书的第11章 标准化和软件知识产权基础知识。</p><h2 id="标准化基础知识" tabindex="-1">标准化基础知识 <a class="header-anchor" href="#标准化基础知识" aria-label="Permalink to &quot;标准化基础知识&quot;">​</a></h2><p>标准是标准化活动的产物，其目的和作用都是通过制定和贯彻具体的标准来体现的。</p><p>标准化不是一个孤立的事物，而是一个活动过程。</p><p>标准化活动过程一般包括标准产生(调查、研究、形成草案、批准发布)子过程、标准实施(宣传、普及、监督、咨询)子过程和标准更新(复审、废止或修订)子过程等。</p><h3 id="标准的分类" tabindex="-1">标准的分类 <a class="header-anchor" href="#标准的分类" aria-label="Permalink to &quot;标准的分类&quot;">​</a></h3><blockquote><p>标准的分类如图所示</p></blockquote><p><img src="'+l+'" alt="ruankao_20241024172951.png" loading="lazy"><img src="'+o+'" alt="ruankao_20241024173018.png" loading="lazy"></p><h3 id="标准的代号和编号" tabindex="-1">标准的代号和编号 <a class="header-anchor" href="#标准的代号和编号" aria-label="Permalink to &quot;标准的代号和编号&quot;">​</a></h3><blockquote><p>标准的代号和编号如图所示</p></blockquote><p><img src="'+t+'" alt="ruankao_20241024174838.png" loading="lazy"></p><h2 id="知识产权基础知识" tabindex="-1">知识产权基础知识 <a class="header-anchor" href="#知识产权基础知识" aria-label="Permalink to &quot;知识产权基础知识&quot;">​</a></h2><p>知识产权(也称为智慧财产权)是现代社会发展中不可缺少的一种法律制度。知识产权是指人们基于自己的智力活动创造的成果和经营管理活动中的经验、知识而依法享有的权利。</p><p>我国《民法通则》规定，知识产权是指民事权利主体(公民、法人)基于创造性的智力成果。</p><h3 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h3><ul><li>知识产权是指民事权利主体（公民、法人）基于创造性的智力成果。</li><li>根据国际公约，知识产权的保护对象包括： <ul><li>①文学、艺术和科学作品；</li><li>②表演艺术家的表演，以及唱片和广播节目；</li><li>③人类一切活动领域的发明；</li><li>④科学发现；</li><li>⑤工业品外观设计；</li><li>⑥商标、服务标记、商业名称和标志；</li><li>⑦制止不正当竞争；</li><li>⑧在工业、科学、文学艺术领域内由于智力创造活动而产生的一切其他权利。</li></ul></li></ul><p>根据世贸协议，知识产权还包括“未披露过的信息专有权”，即商业秘密。</p><blockquote><p>知识产权的分类如图所示</p></blockquote><p><img src="'+p+'" alt="ruankao_20241024175904.png" loading="lazy"></p><p>另外计算机软件和实用艺术品受著作权保护的同时，权利人还可以通过申请发明专利和外观设计专利获得专利权（工业产权）。</p><blockquote><p>知识产权的特点如下</p></blockquote><p>无形性（智力成果）、双重性（多权并存）、确认性（依法审查）、独占性（权利人的相对性）、地域性、时间性。</p><h3 id="计算机软件著作权" tabindex="-1">计算机软件著作权 <a class="header-anchor" href="#计算机软件著作权" aria-label="Permalink to &quot;计算机软件著作权&quot;">​</a></h3><blockquote><p>计算机软件著作权的权利如图所示</p></blockquote><p><img src="'+_+'" alt="ruankao_20241024180520.png" loading="lazy"></p><blockquote><p>计算机软件著作权的行使如图所示。</p></blockquote><p><img src="'+s+'" alt="ruankao_20241024180610.png" loading="lazy"></p><h3 id="计算机软件的商业秘密" tabindex="-1">计算机软件的商业秘密 <a class="header-anchor" href="#计算机软件的商业秘密" aria-label="Permalink to &quot;计算机软件的商业秘密&quot;">​</a></h3><ul><li>商业秘密的构成条件：①未公开的；②具有经济效益的；③采取了保密措施的。</li><li>侵犯计算机软件商业秘密的表现形式：非法获得、非法使用、违约和明知故犯。</li></ul><h3 id="专利权概述" tabindex="-1">专利权概述 <a class="header-anchor" href="#专利权概述" aria-label="Permalink to &quot;专利权概述&quot;">​</a></h3><ul><li>我国专利法主要保护的对象：发明、实用新型和外观设计。</li><li>授予专利权的条件：新颖性、创造性和实用性。</li><li>专利申请日（关键日）是专利局或专利局指定的专利申请受理代办处收到完整专利申请文件的日期，邮寄以寄出的邮戳日为准。</li><li>专利权的保护期限：发明专利权自申请日起 20 年，实用新型和外观设计自申请日起 10 年.</li></ul><h3 id="企业知识产权的保护" tabindex="-1">企业知识产权的保护 <a class="header-anchor" href="#企业知识产权的保护" aria-label="Permalink to &quot;企业知识产权的保护&quot;">​</a></h3><p>企业保护软件知识产权成果的途径</p><p>①明确软件知识产权的归属；②及时对软件技术秘密采取保护措施；③依靠专利保护新技术和新产品；④软件产品进入市场之前的商标权和商业秘密保护权；⑤软件产品进入市场之前申请登记软件著作权。</p>',36)])])}const x=e(c,[["render",u]]);export{f as __pageData,x as default};
